class Solution {
    public int[] intersection(int[] nums1,int[] nums2){
        Set<Integer> first=new HashSet<>();
        for(int value:nums1)first.add(value);
        Set<Integer> common=new TreeSet<>();
        for(int value:nums2)if(first.contains(value))common.add(value);
        return common.stream().mapToInt(Integer::intValue).toArray();
    }
}

code.kotlin:
class Solution {
    fun intersection(nums1:IntArray,nums2:IntArray):IntArray{
        val first=nums1.toHashSet();
        return nums2.filter{
            it in first
        }.distinct().sorted().toIntArray()
    }
}

code.cpp:
class Solution {
    public: vector<int> intersection(vector<int>& nums1,vector<int>& nums2){
        unordered_set<int> first(nums1.begin(),nums1.end());
        set<int> common;
        for(int value:nums2)if(first.count(value))common.insert(value);
        return vector<int>(common.begin(),common.end());
    }
};
